    expect(formatClock(12, 0, "12")).toBe("12pm");
    expect(formatClock(15, 30, "12")).toBe("3:30pm");
    expect(formatClock(9, 0, "24", true)).toBe("09");
    expect(formatClock(21, 45, "24")).toBe("21:45");
