import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App";
import "./index.css";
import "@fontsource/outfit/latin-400.css";
import "@fontsource/outfit/latin-500.css";
import "@fontsource/outfit/latin-600.css";
import "@fontsource/outfit/latin-700.css";
import "@fontsource/ibm-plex-mono/latin-400.css";
import "@fontsource/ibm-plex-mono/latin-600.css";

const root = document.getElementById("root");
if (!root) throw new Error("Missing root");

createRoot(root).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

:root {
  --ink: #142433;
  --ink-soft: #3c5164;
  --muted: #5c7184;
  --harbor: #d5e2eb;
  --sheet: #f7fafc;
  --white: #ffffff;
  --line: #d2dee7;
  --line-strong: #8ea3b4;
  --sleep: #e4edf3;
  --sleep-text: #3e5262;
  --signal: #0f6a3a;
  --signal-ink: #ffffff;
  --teal: #0c6174;
  --teal-soft: #e5f4f7;
  --warn-bg: #f8e6df;
  --warn-ink: #7c2d12;
  --header: #e7eef4;
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
  color: var(--ink);
  background: var(--harbor);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.45;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--harbor);
}

button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
p { margin: 0; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

.app {
  max-width: 1180px;
  margin: 0 auto;
  padding: 28px 20px 48px;
}

.top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 14px;
  border-bottom: 2px solid var(--ink);
}

h1 {
  margin: 0;
  font-size: 2rem;
  font-weight: 650;
  letter-spacing: -0.03em;
  line-height: 1;
}

.lede {
  margin-top: 6px;
  color: var(--ink-soft);
  max-width: 36rem;
}

.mode { text-align: right; }

.mode-help {
  margin-top: 6px;
  color: var(--muted);
  font-size: 0.86rem;
}

.segment {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  background: #c5d4e0;
  border-radius: 10px;
}

.segment button {
  border: 0;
  background: transparent;
  border-radius: 8px;
  min-height: 36px;
  padding: 0 14px;
  font-weight: 600;
  color: var(--ink-soft);
}

.segment button[aria-pressed="true"] {
  background: var(--white);
  color: var(--ink);
}

.sheet {
  margin-top: 16px;
  background: var(--sheet);
  border: 1px solid #9aafbf;
  border-radius: 12px;
}

.settings-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 320px);
  gap: 18px 28px;
  align-items: end;
  padding: 16px 16px 14px;
  border-bottom: 1px solid var(--line);
}

.settings {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
}

.settings legend {
  padding: 0;
  margin-bottom: 8px;
  font-weight: 650;
  font-size: 0.95rem;
}

.field-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 600;
}

.awake-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 8px 10px;
}

.awake-controls label { display: block; }

select, .search input {
  height: 40px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--white);
  padding: 0 12px;
}

select {
  appearance: none;
  min-width: 108px;
  padding-right: 30px;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-soft) 50%), linear-gradient(135deg, var(--ink-soft) 50%, transparent 50%);
  background-position: calc(100% - 16px) 17px, calc(100% - 11px) 17px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.to {
  align-self: center;
  margin-top: 18px;
  color: var(--muted);
  font-size: 0.9rem;
}

.awake-readout {
  margin-top: 8px;
  color: var(--ink-soft);
  font-size: 0.9rem;
}

.search { position: relative; min-width: 0; }

.search input {
  width: 100%;
  font-size: 16px;
}

.search input:disabled {
  background: var(--sleep);
  color: var(--muted);
}

.search-list {
  position: absolute;
  z-index: 6;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  max-height: 320px;
  overflow: auto;
  background: var(--white);
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  box-shadow: 0 8px 20px rgba(20, 36, 51, 0.12);
}

.region {
  margin: 0;
  padding: 8px 12px 2px;
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 650;
}

.option {
  display: flex;
  width: 100%;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 8px 12px;
  border: 0;
  background: transparent;
  text-align: left;
}

.option.is-active, .option:hover { background: var(--teal-soft); }

.option-name { display: block; font-weight: 600; }
.option-country { display: block; color: var(--muted); font-size: 0.78rem; }
.option-offset {
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--ink-soft);
  white-space: nowrap;
}

.search-empty {
  padding: 12px;
  color: var(--muted);
}

.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.summary.is-open { background: #eef8f2; }

.summary-lead { font-weight: 600; }
.summary-lead strong {
  font-family: var(--mono);
  font-weight: 600;
  color: var(--signal);
}

.badges { display: flex; flex-wrap: wrap; gap: 6px; }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 6px;
  background: #ddf3e6;
  color: #085231;
  font-family: var(--mono);
  font-size: 0.78rem;
  font-weight: 600;
}

.base-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.base-list li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.who { min-width: 8.5rem; font-weight: 650; }
.count {
  font-family: var(--mono);
  font-size: 0.82rem;
  color: var(--ink-soft);
}

.warn {
  margin: 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--warn-bg);
  color: var(--warn-ink);
  font-weight: 650;
}

.warn.inline { padding: 4px 8px; }

.empty {
  padding: 28px 16px;
  color: var(--ink-soft);
}

.axis {
  padding: 10px 16px 0;
  color: var(--muted);
  font-size: 0.82rem;
}

.scroller { overflow-x: auto; }

.desktop-table, .mobile-table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
}

.desktop-table {
  table-layout: fixed;
  min-width: 1480px;
}

.desktop-table .corner,
.desktop-table .city-cell { width: 228px; }

.desktop-table .remove-head,
.desktop-table .remove-cell { width: 52px; }

.tick, .cell, .corner, .city-cell, .remove-cell, .city-head {
  border-bottom: 1px solid var(--line);
  border-right: 1px solid var(--line);
}

.tick {
  position: relative;
  height: 42px;
  background: var(--header);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
}

.tick.overlap {
  background: var(--signal);
  color: var(--signal-ink);
  font-weight: 700;
  border-color: #0c5a32;
}

.corner {
  position: sticky;
  left: 0;
  z-index: 3;
  background: var(--header);
  text-align: left;
  padding-left: 12px;
  font-size: 0.75rem;
  font-weight: 650;
  color: var(--muted);
}

.city-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--sheet);
  text-align: left;
  padding: 8px 12px;
  vertical-align: middle;
}

tr.is-reference .city-cell,
.city-head.is-reference { background: var(--teal-soft); }

.cell {
  height: 46px;
  padding: 0 2px;
  text-align: center;
  vertical-align: middle;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms ease, color 140ms ease;
}

.cell.sleep {
  background: var(--sleep);
  color: var(--sleep-text);
  font-weight: 400;
}

.cell.awake {
  background: var(--white);
  color: var(--ink);
}

.cell.overlap {
  background: var(--signal);
  color: var(--signal-ink);
  font-weight: 700;
  border-color: #0c5a32;
}

.cell.is-now, .tick.is-now { box-shadow: inset 0 -3px 0 var(--teal); }
.tick.overlap.is-now { box-shadow: inset 0 -3px 0 #d7fff0; }

.now-dot {
  position: absolute;
  top: 5px;
  left: 50%;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: 50%;
  background: var(--teal);
}

.tick.overlap .now-dot { background: var(--white); }

.identity { min-width: 0; }
.city-line {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.city-name {
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

button.city-name {
  border: 0;
  padding: 0;
  background: transparent;
  text-align: left;
  text-decoration: underline dotted transparent;
  text-underline-offset: 3px;
}

button.city-name:hover {
  color: var(--teal);
  text-decoration-color: var(--teal);
}

.ref {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal);
  color: white;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.country {
  margin-top: 1px;
  color: var(--muted);
  font-size: 0.75rem;
}

.meta {
  display: flex;
  gap: 8px;
  margin-top: 3px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
}

.now::before { content: "· "; color: var(--muted); }

.remove-cell { text-align: center; background: var(--sheet); }

.remove {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}

.remove:hover {
  background: var(--warn-bg);
  color: var(--warn-ink);
}

.mobile-table { min-width: 100%; }

.mobile-table .hour-label {
  position: sticky;
  left: 0;
  z-index: 2;
  width: 72px;
  min-width: 72px;
  background: var(--header);
}

.mobile-table .city-head {
  width: 148px;
  min-width: 148px;
  padding: 10px 8px 8px;
  vertical-align: top;
  text-align: left;
  background: var(--sheet);
}

.mobile-table .identity { margin-bottom: 6px; }
.mobile-table .city-name { font-size: 0.88rem; }

.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 16px;
  padding: 12px 16px 14px;
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
