}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--harbor);
}

button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
p { margin: 0; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

.app {
  max-width: 1180px;
  margin: 0 auto;
  padding: 28px 20px 48px;
}

.top {
  display: flex;
