  font-weight: 650;
  letter-spacing: -0.03em;
  line-height: 1;
}

.lede {
  margin-top: 6px;
  color: var(--ink-soft);
  max-width: 36rem;
}

.mode { text-align: right; }

.mode-help {
  margin-top: 6px;
  color: var(--muted);
  font-size: 0.86rem;
}

.segment {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  background: #c5d4e0;
  border-radius: 10px;
}

.segment button {
  border: 0;
  background: transparent;
  border-radius: 8px;
  min-height: 36px;
  padding: 0 14px;
  font-weight: 600;
  color: var(--ink-soft);
}

.segment button[aria-pressed="true"] {
  background: var(--white);
  color: var(--ink);
}

.sheet {
  margin-top: 16px;
  background: var(--sheet);
  border: 1px solid #9aafbf;
  border-radius: 12px;
}

.controls {
  padding: 16px 16px 14px;
  border-bottom: 1px solid var(--line);
}

.settings-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 320px);
  gap: 18px 28px;
  align-items: end;
}

.settings {
  margin: 0;
  padding: 0;
  border: 0;
