  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.country {
  margin-top: 1px;
  color: var(--muted);
  font-size: 0.75rem;
}

.meta {
  display: flex;
  gap: 8px;
  margin-top: 3px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
}

.now::before { content: "· "; color: var(--muted); }

