  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}

.remove:hover {
  background: var(--warn-bg);
  color: var(--warn-ink);
}

.mobile-table { min-width: 100%; }

.mobile-table .hour-label {
  position: sticky;
  left: 0;
  z-index: 2;
  width: 72px;
  min-width: 72px;
  background: var(--header);
}

.mobile-table .city-head {
  width: 148px;
  min-width: 148px;
  padding: 10px 8px 8px;
