.empty {
  padding: 28px 16px;
  color: var(--ink-soft);
}

.axis {
  padding: 10px 16px 0;
  color: var(--muted);
  font-size: 0.82rem;
}

.scroller { overflow-x: auto; }

.desktop-table, .mobile-table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
}

.desktop-table {
  table-layout: fixed;
  min-width: 1480px;
}

.desktop-table .corner,
.desktop-table .city-cell { width: 228px; }

.desktop-table .remove-head,
.desktop-table .remove-cell { width: 52px; }

.tick, .cell, .corner, .city-cell, .remove-cell, .city-head {
  border-bottom: 1px solid var(--line);
  border-right: 1px solid var(--line);
}

.tick {
  position: relative;
  height: 42px;
  background: var(--header);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
}

.tick.overlap {
  background: var(--signal);
  color: var(--signal-ink);
  font-weight: 700;
  border-color: #0c5a32;
}

.corner {
  position: sticky;
  left: 0;
  z-index: 3;
  background: var(--header);
  text-align: left;
  padding-left: 12px;
  font-size: 0.75rem;
  font-weight: 650;
  color: var(--muted);
}

.city-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--sheet);
  text-align: left;
  padding: 8px 12px;
  vertical-align: middle;
}

tr.is-reference .city-cell,
.city-head.is-reference { background: var(--teal-soft); }

.cell {
  height: 46px;
  padding: 0 2px;
  text-align: center;
  vertical-align: middle;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms ease, color 140ms ease;
}

.cell.sleep {
  background: var(--sleep);
  color: var(--sleep-text);
  font-weight: 400;
}

.cell.awake {
  background: var(--white);
  color: var(--ink);
}

.cell.overlap {
  background: var(--signal);
  color: var(--signal-ink);
  font-weight: 700;
  border-color: #0c5a32;
}

.cell.is-now, .tick.is-now { box-shadow: inset 0 -3px 0 var(--teal); }
.tick.overlap.is-now { box-shadow: inset 0 -3px 0 #d7fff0; }

.now-dot {
  position: absolute;
  top: 5px;
  left: 50%;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: 50%;
  background: var(--teal);
}

.tick.overlap .now-dot { background: var(--white); }

.identity { min-width: 0; }
.city-line {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.city-name {
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

button.city-name {
  border: 0;
  padding: 0;
  background: transparent;
  text-align: left;
  text-decoration: underline dotted transparent;
  text-underline-offset: 3px;
}

button.city-name:hover {
  color: var(--teal);
  text-decoration-color: var(--teal);
}

.ref {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal);
  color: white;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.country {
  margin-top: 1px;
  color: var(--muted);
  font-size: 0.75rem;
}

.meta {
  display: flex;
  gap: 8px;
  margin-top: 3px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
}

.now::before { content: "· "; color: var(--muted); }

.remove-cell { text-align: center; background: var(--sheet); }

.remove {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}

.remove:hover {
  background: var(--warn-bg);
  color: var(--warn-ink);
}

.mobile-table { min-width: 100%; }

.mobile-table .hour-label {
  position: sticky;
  left: 0;
  z-index: 2;
  width: 72px;
  min-width: 72px;
  background: var(--header);
}

.mobile-table .city-head {
  width: 148px;
  min-width: 148px;
  padding: 10px 8px 8px;
  vertical-align: top;
  text-align: left;
  background: var(--sheet);
}

.mobile-table .identity { margin-bottom: 6px; }
.mobile-table .city-name { font-size: 0.88rem; }

.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 16px;
  padding: 12px 16px 14px;
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--ink-soft);
  font-size: 0.82rem;
}

.legend li { display: flex; align-items: center; gap: 6px; }

.swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid var(--line-strong);
}

.swatch.overlap { background: var(--signal); border-color: var(--signal); }
.swatch.awake { background: var(--white); }
.swatch.sleep { background: var(--sleep); }

.hint {
  margin: 0;
  color: var(--ink);
  font-weight: 600;
}

@media (max-width: 767px) {
  .app { padding: 18px 12px 32px; }
  h1 { font-size: 1.7rem; }
  .top { flex-direction: column; align-items: stretch; gap: 14px; }
  .mode { text-align: left; }
  .segment { display: flex; }
  .segment button { flex: 1; }
  .controls { padding: 14px 12px; }
  .settings-grid { grid-template-columns: 1fr; }
  .awake-controls { align-items: stretch; }
  .awake-controls label { flex: 1; }
  select { width: 100%; }
  .to { margin: 22px 0 0; }
  .remove { width: 44px; height: 44px; }
  .foot { align-items: flex-start; flex-direction: column; }
}

@media (prefers-reduced-motion: reduce) {
  .cell { transition: none; }
}

