  height: 42px;
  background: var(--header);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
}

.tick.overlap {
  background: var(--signal);
  color: var(--signal-ink);
  font-weight: 700;
  border-color: #0c5a32;
}

.corner {
