.tick.overlap.is-now { box-shadow: inset 0 -3px 0 #d7fff0; }

.now-dot {
  position: absolute;
  top: 5px;
  left: 50%;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: 50%;
  background: var(--teal);
}

.tick.overlap .now-dot { background: var(--white); }

.identity { min-width: 0; }
.city-line {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.city-name {
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

button.city-name {
  border: 0;
  padding: 0;
  background: transparent;
  text-align: left;
  text-decoration: underline dotted transparent;
  text-underline-offset: 3px;
}

button.city-name:hover {
  color: var(--teal);
