}

.ref {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal);
  color: white;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.country {
  margin-top: 1px;
  color: var(--muted);
  font-size: 0.75rem;
}

.meta {
  display: flex;
  gap: 8px;
  margin-top: 3px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
}

.now::before { content: "· "; color: var(--muted); }

.remove-cell { text-align: center; background: var(--sheet); }

.remove {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}

.remove:hover {
  background: var(--warn-bg);
  color: var(--warn-ink);
}

.mobile-table { min-width: 100%; }

.mobile-table .hour-label {
  position: sticky;
  left: 0;
  z-index: 2;
  width: 72px;
  min-width: 72px;
  background: var(--header);
}

.mobile-table .city-head {
  width: 148px;
  min-width: 148px;
  padding: 10px 8px 8px;
  vertical-align: top;
  text-align: left;
  background: var(--sheet);
}

.mobile-table .identity { margin-bottom: 6px; }
.mobile-table .city-name { font-size: 0.88rem; }

.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 16px;
  padding: 12px 16px 14px;
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--ink-soft);
  font-size: 0.82rem;
}

.legend li { display: flex; align-items: center; gap: 6px; }

.swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid var(--line-strong);
}

.swatch.overlap { background: var(--signal); border-color: var(--signal); }
.swatch.awake { background: var(--white); }
.swatch.sleep { background: var(--sleep); }

.hint {
  margin: 0;
  color: var(--ink);
  font-weight: 600;
}

@media (max-width: 767px) {
