  align-items: center;
  gap: 8px;
}

.who { min-width: 8.5rem; font-weight: 650; }
.count {
  font-family: var(--mono);
  font-size: 0.82rem;
  color: var(--ink-soft);
}

.warn {
  margin: 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--warn-bg);
  color: var(--warn-ink);
  font-weight: 650;
}

.warn.inline { padding: 4px 8px; }

.empty {
  padding: 28px 16px;
  color: var(--ink-soft);
}

.axis {
  padding: 10px 16px 0;
  color: var(--muted);
  font-size: 0.82rem;
}

.scroller { overflow-x: auto; }

.desktop-table, .mobile-table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
}

.desktop-table {
