}

.base-list li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.who { min-width: 8.5rem; font-weight: 650; }
.count {
  font-family: var(--mono);
  font-size: 0.82rem;
  color: var(--ink-soft);
}

.warn {
  margin: 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--warn-bg);
  color: var(--warn-ink);
  font-weight: 650;
}

.warn.inline { padding: 4px 8px; }

.empty {
  padding: 28px 16px;
  color: var(--ink-soft);
}

.axis {
  padding: 10px 16px 0;
  color: var(--muted);
  font-size: 0.82rem;
}

.scroller { overflow-x: auto; }

.desktop-table, .mobile-table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
}

.desktop-table {
  table-layout: fixed;
  min-width: 1040px;
}

.col-city { width: 196px; }
.col-remove { width: 46px; }

.tick, .cell, .corner, .city-cell, .remove-cell, .city-head {
  border-bottom: 1px solid var(--line);
  border-right: 1px solid var(--line);
}

.tick {
  position: relative;
  height: 42px;
  background: var(--header);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: -0.03em;
  text-align: center;
  white-space: nowrap;
}

.tick.overlap {
  background: var(--signal);
  color: var(--signal-ink);
  font-weight: 700;
  border-color: #0c5a32;
}

.corner {
  position: sticky;
  left: 0;
  z-index: 3;
  background: var(--header);
  text-align: left;
  padding-left: 12px;
  font-size: 0.75rem;
  font-weight: 650;
  color: var(--muted);
}

.city-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--sheet);
  text-align: left;
  padding: 8px 12px;
  vertical-align: middle;
}

tr.is-reference .city-cell,
.city-head.is-reference { background: var(--teal-soft); }

.cell {
  height: 48px;
  padding: 0 1px;
  text-align: center;
  vertical-align: middle;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 1.15;
  white-space: nowrap;
  transition: background-color 140ms ease, color 140ms ease;
}

.cell-hour, .cell-suffix { display: block; }
