.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.summary.is-open { background: #eef8f2; }

.summary-lead { font-weight: 600; }
.summary-lead strong {
  font-family: var(--mono);
  font-weight: 600;
  color: var(--signal);
}

.badges { display: flex; flex-wrap: wrap; gap: 6px; }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 6px;
  background: var(--signal);
