}

.warn.inline { padding: 4px 8px; }

.empty {
  padding: 28px 16px;
  color: var(--ink-soft);
}

.axis {
  padding: 10px 16px 0;
  color: var(--muted);
  font-size: 0.82rem;
}

.scroller { overflow-x: auto; }

.desktop-table, .mobile-table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
}

.desktop-table {
  table-layout: fixed;
  min-width: 1040px;
}

.col-city { width: 196px; }
.col-remove { width: 46px; }

.tick, .cell, .corner, .city-cell, .remove-cell, .city-head {
  border-bottom: 1px solid var(--line);
  border-right: 1px solid var(--line);
}

.tick {
  position: relative;
  height: 42px;
  background: var(--header);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: -0.03em;
  text-align: center;
  white-space: nowrap;
}

.tick.overlap {
  background: var(--signal);
