  font-weight: 700;
  border-color: #0c5a32;
}

.corner {
  position: sticky;
  left: 0;
  z-index: 3;
  background: var(--header);
  text-align: left;
  padding-left: 12px;
  font-size: 0.75rem;
  font-weight: 650;
  color: var(--muted);
}

.city-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--sheet);
  text-align: left;
  padding: 8px 12px;
  vertical-align: middle;
}

tr.is-reference .city-cell,
.city-head.is-reference { background: var(--teal-soft); }

.cell {
  height: 48px;
  padding: 0 1px;
  text-align: center;
  vertical-align: middle;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 1.15;
  white-space: nowrap;
  transition: background-color 140ms ease, color 140ms ease;
}

.cell-hour, .cell-suffix { display: block; }
.cell-suffix { font-size: 10px; font-weight: 600; }

.cell.sleep {
  background: var(--sleep);
