dev-browser <<'EOF'
const page = await browser.getPage("tz-board");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
await page.setViewportSize({ width: 1440, height: 960 });
await page.goto("http://127.0.0.1:9339/", { waitUntil: "networkidle" });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: "networkidle" });
await page.waitForSelector(".desktop-table");
const metrics = await page.evaluate(() => {
  const scroller = document.querySelector('[data-layout="desktop"]');
  const ticks = [...document.querySelectorAll(".desktop-table thead .tick")].map((th) => th.textContent.replace("Current hour", "").trim());
  const remove = document.querySelector(".remove");
  const box = remove.getBoundingClientRect();
  const last = document.querySelector('.desktop-table thead .tick[data-hour="23"]').getBoundingClientRect();
  const overlapHours = [...document.querySelectorAll(".desktop-table thead .tick.overlap")].map((th) => th.getAttribute("data-hour"));
  return {
    overflow: scroller.scrollWidth - scroller.clientWidth,
    ticks,
    overlapHours,
    removeVisible: box.right <= window.innerWidth && box.left >= 0 && box.width > 0,
    lastRight: Math.round(last.right),
    inner: window.innerWidth,
  };
});
const shot = await page.screenshot({ fullPage: true });
const path = await saveScreenshot(shot, "desktop-fit.png");
console.log(JSON.stringify({ errors, path, metrics }, null, 2));
EOF

