dev-browser <<'EOF'
const page = await browser.getPage("tz-board");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
await page.setViewportSize({ width: 1440, height: 1000 });
await page.goto("http://127.0.0.1:9339/", { waitUntil: "networkidle" });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: "networkidle" });

const results = {};

await page.getByPlaceholder("Search city or country").fill("sao");
await page.waitForSelector(".option");
results.sao = await page.locator(".option-name").allTextContents();
await page.getByPlaceholder("Search city or country").fill("mumbai");
await page.getByRole("option", { name: /Mumbai/ }).click();
await page.getByPlaceholder("Search city or country").fill("kathmandu");
await page.getByRole("option", { name: /Kathmandu/ }).click();
await page.getByPlaceholder("Search city or country").fill("mumbai");
results.mumbaiDuplicate = await page.locator(".search-empty").textContent().catch(() => "no-empty");
await page.keyboard.press("Escape");

results.fractional = await page.evaluate(() => {
  const row = (id) => [...document.querySelectorAll(`tr[data-city="${id}"] td.cell`)].map((td) => ({
    h: td.getAttribute("data-hour"),
    state: td.getAttribute("data-state"),
    text: td.innerText.replace(/\n/g, ""),
  }));
  return {
    mumbai: row("mumbai").filter((cell) => cell.text.includes(":")),
    kathmandu: row("kathmandu").filter((cell) => cell.text.includes(":")),
  };
});

await page.getByRole("button", { name: "Make Geneva the reference city" }).click();
results.afterPromote = await page.evaluate(() => ({
  first: document.querySelector("tbody tr")?.getAttribute("data-city"),
  summary: document.querySelector(".summary")?.innerText,
}));

await page.getByRole("button", { name: "Base", exact: true }).click();
results.base = await page.evaluate(() => {
  const rows = [...document.querySelectorAll("tbody tr")].map((tr) => ({
    city: tr.getAttribute("data-city"),
