  font-size: 0.78rem;
  font-weight: 600;
}

.base-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.base-list li {
  display: flex;
