  margin-top: 1px;
  color: var(--muted);
  font-size: 0.75rem;
}

.meta {
  display: flex;
  gap: 8px;
  margin-top: 3px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 11px;
}

.now::before { content: "· "; color: var(--muted); }

.remove-head, .remove-cell {
  position: sticky;
  right: 0;
  z-index: 2;
  background: var(--sheet);
  box-shadow: -1px 0 0 var(--line);
}

.remove-head {
  z-index: 3;
  background: var(--header);
}

tr.is-reference .remove-cell { background: var(--teal-soft); }

.remove-cell { text-align: center; }

.remove {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}

.remove:hover {
  background: var(--warn-bg);
  color: var(--warn-ink);
}

.mobile-table {
  width: 100%;
  min-width: 100%;
  table-layout: fixed;
}

.mobile-table .hour-label {
  position: sticky;
  left: 0;
  z-index: 2;
  width: 54px;
  min-width: 54px;
  background: var(--header);
}

.mobile-table .city-head {
  padding: 8px 6px 6px;
  vertical-align: top;
  text-align: left;
  background: var(--sheet);
}

.mobile-table .identity { margin-bottom: 4px; }
.mobile-table .city-name { font-size: 0.8rem; white-space: normal; }
.mobile-table .meta { flex-wrap: wrap; }

.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 16px;
  padding: 12px 16px 14px;
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--ink-soft);
  font-size: 0.82rem;
}

.legend li { display: flex; align-items: center; gap: 6px; }

.swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid var(--line-strong);
}

.swatch.overlap { background: var(--signal); border-color: var(--signal); }
.swatch.awake { background: var(--white); }
.swatch.sleep { background: var(--sleep); }

.hint {
  margin: 0;
  color: var(--ink);
  font-weight: 600;
}

@media (max-width: 767px) {
  .app { padding: 18px 12px 32px; }
  h1 { font-size: 1.7rem; }
  .top { flex-direction: column; align-items: stretch; gap: 14px; }
  .mode { text-align: left; }
  .segment { display: flex; }
  .segment button { flex: 1; }
  .controls { padding: 14px 12px; }
  .settings-grid { grid-template-columns: 1fr; }
  .awake-controls { align-items: stretch; }
  .awake-controls label { flex: 1; }
  select { width: 100%; }
  .to { margin: 22px 0 0; }
  .remove { width: 44px; height: 44px; }
  .foot { align-items: flex-start; flex-direction: column; }
}

@media (prefers-reduced-motion: reduce) {
  .cell { transition: none; }
}

