  const firstRows = [...document.querySelectorAll(".mobile-table tbody tr")].slice(0, 3).map((tr) => ({
    hour: tr.querySelector("th")?.innerText.replace("Current hour", "").trim(),
    cells: [...tr.querySelectorAll("td")].map((td) => ({ state: td.getAttribute("data-state"), text: td.innerText.replace(/\n/g, "") })),
  }));
  const overlapRows = [...document.querySelectorAll(".mobile-table tbody tr")].filter((tr) => tr.querySelector("th.overlap")).map((tr) => tr.querySelector("th")?.getAttribute("data-hour"));
  return {
    layout: document.querySelector("[data-layout]")?.getAttribute("data-layout"),
    desktopMounted: Boolean(document.querySelector('[data-layout="desktop"]')),
    title: document.title,
    h1: document.querySelector("h1")?.textContent,
    hint: document.querySelector(".hint")?.textContent.trim(),
    summary: document.querySelector(".summary")?.innerText,
    headerCities,
    overflow: scroller.scrollWidth - scroller.clientWidth,
    tableWidth: Math.round(table.getBoundingClientRect().width),
    viewport: window.innerWidth,
    firstRows,
    overlapRows,
    removeCount: document.querySelectorAll(".remove").length,
  };
});
const mobileShot = await page.screenshot({ fullPage: true });
const mobilePath = await saveScreenshot(mobileShot, "mobile-default.png");

await page.setViewportSize({ width: 800, height: 900 });
await page.waitForSelector('[data-layout="desktop"]');
const narrow = await page.evaluate(() => {
  const scroller = document.querySelector(".scroller");
  const city = document.querySelector(".city-cell").getBoundingClientRect();
  scroller.scrollLeft = 400;
  const cityAfter = document.querySelector(".city-cell").getBoundingClientRect();
  const remove = document.querySelector(".remove-cell").getBoundingClientRect();
  return {
    layout: document.querySelector("[data-layout]")?.getAttribute("data-layout"),
    overflow: scroller.scrollWidth > scroller.clientWidth,
    cityLeft: Math.round(cityAfter.left),
    removeRight: Math.round(remove.right),
    inner: window.innerWidth,
  };
});

await page.getByRole("button", { name: "Base", exact: true }).click();
const refCell = await page.evaluate(() => {
  const cell = document.querySelector('tr.is-reference td[data-hour="7"]');
  const style = getComputedStyle(cell);
  return { state: cell.getAttribute("data-state"), bg: style.backgroundColor, nowCount: document.querySelectorAll(".is-now").length, rows: document.querySelectorAll("tbody tr").length };
});

console.log(JSON.stringify({ errors, mobilePath, mobile, narrow, refCell }, null, 2));
