success.beforeFullFileContent:
:root {
  --ink: #142433;
  --ink-soft: #3c5164;
  --muted: #5c7184;
  --harbor: #d5e2eb;
  --sheet: #f7fafc;
  --white: #ffffff;
  --line: #d2dee7;
  --line-strong: #8ea3b4;
  --sleep: #c9d7e3;
  --sleep-text: #2f4556;
  --signal: #0f6a3a;
  --signal-ink: #ffffff;
  --teal: #0c6174;
  --teal-soft: #e5f4f7;
  --warn-bg: #f8e6df;
  --warn-ink: #7c2d12;
  --header: #e7eef4;
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
  color: var(--ink);
  background: var(--harbor);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.45;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--harbor);
}

button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
p { margin: 0; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

.app {
  max-width: 1480px;
  margin: 0 auto;
  padding: 28px 16px 48px;
}

.top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 14px;
  border-bottom: 2px solid var(--ink);
}

h1 {
  margin: 0;
  font-size: 2rem;
  font-weight: 650;
  letter-spacing: -0.03em;
  line-height: 1;
}

.lede {
  margin-top: 6px;
  color: var(--ink-soft);
  max-width: 36rem;
}

.mode { text-align: right; }

.mode-help {
  margin-top: 6px;
  color: var(--muted);
  font-size: 0.86rem;
}

.segment {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  background: #c5d4e0;
  border-radius: 10px;
}

.segment button {
  border: 0;
  background: transparent;
  border-radius: 8px;
  min-height: 36px;
  padding: 0 14px;
  font-weight: 600;
  color: var(--ink-soft);
}

.segment button[aria-pressed="true"] {
  background: var(--white);
  color: var(--ink);
}

.sheet {
  margin-top: 16px;
  background: var(--sheet);
  border: 1px solid #9aafbf;
  border-radius: 12px;
}

.controls {
  padding: 16px 16px 14px;
  border-bottom: 1px solid var(--line);
}

.settings-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 320px);
  gap: 18px 28px;
  align-items: end;
}

.settings {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
}

.settings legend {
  padding: 0;
  margin-bottom: 8px;
  font-weight: 650;
  font-size: 0.95rem;
}

.field-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 600;
}

.awake-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 8px 10px;
}

.awake-controls label { display: block; }

select, .search input {
  height: 40px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--white);
  padding: 0 12px;
}

select {
  appearance: none;
  min-width: 108px;
  padding-right: 30px;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-soft) 50%), linear-gradient(135deg, var(--ink-soft) 50%, transparent 50%);
  background-position: calc(100% - 16px) 17px, calc(100% - 11px) 17px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.to {
  align-self: center;
  margin-top: 18px;
  color: var(--muted);
  font-size: 0.9rem;
}

.awake-readout {
  margin-top: 8px;
  color: var(--ink-soft);
  font-size: 0.9rem;
}

.search { position: relative; min-width: 0; }

.search input {
  width: 100%;
  font-size: 16px;
}

.search input:disabled {
  background: var(--sleep);
  color: var(--muted);
}

.search-list {
  position: absolute;
  z-index: 6;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  max-height: 320px;
  overflow: auto;
  background: var(--white);
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  box-shadow: 0 8px 20px rgba(20, 36, 51, 0.12);
}

.region {
  margin: 0;
  padding: 8px 12px 2px;
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 650;
}

.option {
  display: flex;
  width: 100%;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 8px 12px;
  border: 0;
  background: transparent;
  text-align: left;
}

.option.is-active, .option:hover { background: var(--teal-soft); }

.option-name { display: block; font-weight: 600; }
.option-country { display: block; color: var(--muted); font-size: 0.78rem; }
.option-offset {
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--ink-soft);
  white-space: nowrap;
}

.search-empty {
  padding: 12px;
  color: var(--muted);
}

.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.summary.is-open { background: #eef8f2; }

.summary-lead { font-weight: 600; }
.summary-lead strong {
  font-family: var(--mono);
  font-weight: 600;
  color: var(--signal);
}

.badges { display: flex; flex-wrap: wrap; gap: 6px; }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 6px;
  background: var(--signal);
  color: #fff;
  font-family: var(--mono);
  font-size: 0.78rem;
  font-weight: 600;
}

.base-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.base-list li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.who { min-width: 8.5rem; font-weight: 650; }
.count {
  font-family: var(--mono);
  font-size: 0.82rem;
  color: var(--ink-soft);
}

.warn {
  margin: 0;
