  .cell { transition: none; }
}

args.command:
dev-browser <<'EOF'
const page = await browser.getPage("tz-board");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
await page.setViewportSize({ width: 390, height: 844 });
await page.goto("http://127.0.0.1:9339/", { waitUntil: "networkidle" });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: "networkidle" });
await page.waitForSelector('[data-layout="mobile"]');
const fit = await page.evaluate(() => {
  const scroller = document.querySelector('[data-layout="mobile"]');
  return { overflow: scroller.scrollWidth - scroller.clientWidth, cities: document.querySelectorAll(".city-head").length };
});
const top = await page.screenshot({ clip: { x: 0, y: 0, width: 390, height: 780 } });
const topPath = await saveScreenshot(top, "mobile-top.png");

await page.setViewportSize({ width: 1280, height: 800 });
await page.waitForSelector('[data-layout="desktop"]');
await page.getByPlaceholder("Search city or country").click();
await page.keyboard.type("tokyo");
await page.keyboard.press("Enter");
const added = await page.evaluate(() => [...document.querySelectorAll("tbody tr")].map((tr) => tr.getAttribute("data-city")));

await page.getByRole("button", { name: "Base", exact: true }).click();
await page.locator("label").filter({ hasText: "Wake" }).locator("select").selectOption("4");
await page.locator("label").filter({ hasText: "Sleep" }).locator("select").selectOption("5");
await page.waitForTimeout(100);
const baseZero = await page.locator(".summary").innerText();

console.log(JSON.stringify({ errors, fit, topPath, added, baseZero }, null, 2));
EOF

